stubs.usr/libexec/termux/command-not-found:
# 命令没找到（bash.bashrc 的 command_not_found_handle 调它）：模块化工具包（cccodroid 0.3.9 起）里，
# 看看这个命令是不是在还没装的模块里，告诉用户去哪装。整包工具包没有 modules.json，就只报找不到
u=$(cd "$(dirname "$0")/../.." && pwd)
if [ -f "$u/libexec/devkit/modules.json" ] && [ -x "$u/bin/node" ]; then
  "$u/bin/node" -e '
const [f, cmd] = process.argv.slice(1), u = require("path").dirname(require("path").dirname(require("path").dirname(f)));
const mj = JSON.parse(require("fs").readFileSync(f, "utf8"));
const m = (mj.modules || []).find((x) => x.kind === "module" && (x.commands || []).includes(cmd) && !require("fs").existsSync(u + "/" + x.dir + "/.ok"));
if (!m) process.exit(1);
// 连同还没装的依赖（共享层）一起算
const ok = (x) => x.kind === "base" || require("fs").existsSync(u + "/" + x.dir + "/.ok");
const mb = Math.round([m, ...(m.deps || []).map((d) => mj.modules.find((x) => x.id === d)).filter((x) => x && !ok(x))].reduce((s, x) => s + (x.installed || 0), 0) / 1048576);
console.error(cmd + "：在工具包的「" + m.name.zh + "」模块里，还没装。到 扩展 → 工具包模块 装上即可（约 " + mb + " MB）。");
console.error(cmd + ": part of the \u201c" + m.name.en + "\u201d toolkit module, which is not installed. Install it under Extensions \u2192 Toolkit modules (about " + mb + " MB).");
' "$u/libexec/devkit/modules.json" "$1" && exit 127
fi
echo "$1: command not found" >&2
exit 127
